// HTTPDoer sends a request, as *http.Client does.
type HTTPDoer = httpclient.Doer

// RequestEditor changes a request before it is sent.
type RequestEditor func(ctx context.Context, req *http.Request) error

// ClientInterface is what Client implements.
type ClientInterface interface {
	// SendParcel calls POST /parcels.
	SendParcel(ctx context.Context, opts *SendParcelRequestOptions, editors ...RequestEditor) (*Receipt, error)
	// GetParcel calls GET /parcels/{id}.
	GetParcel(ctx context.Context, opts *GetParcelRequestOptions, editors ...RequestEditor) (*Receipt, error)
	// PrintLabel calls POST /labels.
	PrintLabel(ctx context.Context, opts *PrintLabelRequestOptions, editors ...RequestEditor) (*Label, error)
	// CreateCustomer calls POST /customers.
	CreateCustomer(ctx context.Context, opts *CreateCustomerRequestOptions, editors ...RequestEditor) (*Customer, error)
}

var _ ClientInterface = (*Client)(nil)

// ClientOption sets one setting of Client.
type ClientOption func(*Client)

// WithHTTPClient sends the requests with d. A nil d panics.
func WithHTTPClient(d HTTPDoer) ClientOption {
	if d == nil {
		panic("WithHTTPClient: nil HTTPDoer")
	}
	return func(c *Client) {
		c.doer = d
	}
}

// WithTimeout sets how long a call may take, 0 for no limit.
func WithTimeout(d time.Duration) ClientOption {
	return func(c *Client) {
		c.timeout = d
	}
}

// WithRequestEditor runs fns on every request before it is sent. A nil one panics.
func WithRequestEditor(fns ...RequestEditor) ClientOption {
	for _, fn := range fns {
		if fn == nil {
			panic("WithRequestEditor: nil RequestEditor")
		}
	}
	return func(c *Client) {
		c.editors = append(c.editors, fns...)
	}
}

// WithJSON writes JSON bodies with marshal and reads them with unmarshal. A nil one panics.
func WithJSON(marshal func(v any) ([]byte, error), unmarshal func(data []byte, v any) error) ClientOption {
	if marshal == nil || unmarshal == nil {
		panic("WithJSON: nil function")
	}
	return func(c *Client) {
		c.marshal, c.unmarshal = marshal, unmarshal
	}
}

// Client calls the API at a base URL.
// A response outside 2xx, or a 2xx the spec does not list, is a *httpclient.APIError.
type Client struct {
	baseURL   *url.URL
	doer      HTTPDoer
	timeout   time.Duration
	editors   []RequestEditor
	marshal   func(v any) ([]byte, error)
	unmarshal func(data []byte, v any) error
}

// NewClient returns a client of the API at baseURL.
func NewClient(baseURL string, opts ...ClientOption) (*Client, error) {
	u, err := httpclient.ParseBaseURL(baseURL)
	if err != nil {
		return nil, err
	}

	c := &Client{
		baseURL:   u,
		doer:      &http.Client{},
		timeout:   3 * time.Second,
		marshal:   json.Marshal,
		unmarshal: json.Unmarshal,
	}
	for _, opt := range opts {
		opt(c)
	}
	return c, nil
}

// SendParcel calls POST /parcels.
func (c *Client) SendParcel(ctx context.Context, opts *SendParcelRequestOptions, editors ...RequestEditor) (*Receipt, error) {
	req, err := c.SendParcelRequest(ctx, opts, editors...)
	if err != nil {
		return nil, err
	}
	res, body, err := httpclient.Send(c.doer, req, "application/json", c.timeout)
	if err != nil {
		return nil, err
	}

	var out *Receipt
	if err = httpclient.DecodeSuccess(res, body, []httpclient.ResponseTarget{
		{Status: "200", MediaType: "application/json", Dst: &out},
	}, c.unmarshal); err != nil {
		return nil, err
	}
	return out, nil
}

